<?php

declare( strict_types=1 );

namespace LearnPress\Tests\Unit\Security;

use Brain\Monkey\Functions;
use LearnPress\Tests\Helpers\BrainMonkeyTestCase;
use LP_Widget;

if ( ! class_exists( 'WP_Widget' ) ) {
	// phpcs:ignore
	eval( 'class WP_Widget { public $lp_test_settings = []; public function __construct( ...$args ) {} public function get_settings() { return $this->lp_test_settings; } }' );
}

require_once dirname( __DIR__, 3 ) . '/inc/class-lp-widget.php';

/**
 * Regression test: REST API lp/v1/widgets/api only accepts widget instance generated by server.
 *
 * Before the fix, the client could send any `instance` (limit, course_id...) and the `hash` was ignored.
 */
class WidgetInstanceSignatureTest extends BrainMonkeyTestCase {

	protected function setUp(): void {
		parent::setUp();

		Functions\when( 'wp_hash' )->alias(
			static function ( $data ) {
				return hash_hmac( 'md5', $data, 'secret-salt' );
			}
		);
		Functions\when( 'wp_json_encode' )->alias( 'json_encode' );
	}

	private function make_widget( array $settings_saved = [] ): LP_Widget {
		$widget                   = new LP_Widget();
		$widget->widget_id        = 'learnpress_widget_course_popular';
		$widget->lp_test_settings = $settings_saved;

		return $widget;
	}

	public function test_verify_instance_accepts_instance_signed_by_server(): void {
		$widget        = $this->make_widget();
		$instance_json = json_encode( [ 'limit' => 4, 'title' => 'Khóa học / "A"' ] );
		$hash          = LP_Widget::sign_instance( $widget->widget_id, $instance_json );

		$this->assertTrue( $widget->verify_instance( $instance_json, $hash ) );
	}

	public function test_verify_instance_rejects_instance_changed_by_client(): void {
		$widget = $this->make_widget();
		$hash   = LP_Widget::sign_instance( $widget->widget_id, json_encode( [ 'limit' => 4 ] ) );

		$this->assertFalse( $widget->verify_instance( json_encode( [ 'limit' => -1 ] ), $hash ) );
	}

	public function test_verify_instance_rejects_missing_hash(): void {
		$widget = $this->make_widget();

		$this->assertFalse( $widget->verify_instance( json_encode( [ 'limit' => -1 ] ), '' ) );
		$this->assertFalse( $widget->verify_instance( 'not-json', '' ) );
	}

	public function test_verify_instance_rejects_hash_of_another_widget(): void {
		$widget        = $this->make_widget();
		$instance_json = json_encode( [ 'course_id' => 99 ] );
		$hash          = LP_Widget::sign_instance( 'learnpress_widget_course_extra', $instance_json );

		$this->assertFalse( $widget->verify_instance( $instance_json, $hash ) );
	}

	public function test_verify_instance_accepts_instance_saved_in_widget_settings_without_hash(): void {
		$widget = $this->make_widget(
			[
				2              => [ 'limit' => 4, 'title' => 'Popular' ],
				'_multiwidget' => 1,
			]
		);

		$this->assertTrue( $widget->verify_instance( json_encode( [ 'limit' => 4, 'title' => 'Popular' ] ), '' ) );
		$this->assertFalse( $widget->verify_instance( json_encode( [ 'limit' => 500, 'title' => 'Popular' ] ), '' ) );
	}
}
